//https://www.acwing.com/problem/content/8/
#include <bits/stdc++.h>
using namespace std;
const int N=1010;
int n,V,M;
int v[N],w[N],m[N];
int mem[N][N];
int dfs(int x,int spV,int spM)
{
    if (x>n) return 0;
    int sum=0;
    if(mem[x][spV]) return mem[x][spV];
    if(spV<v[x]||spM<m[x])
        sum=dfs(x+1,spV,spM);
    else if(spV>=v[x]&&spM>=m[x])
        sum=max(dfs(x+1,spV,spM),dfs(x+1,spV-v[x],spM-m[x]))+w[x];
    mem[x][spV]=sum;
    return sum;
}
int main()
{
    cin>>n>>V>>M;
    for(int i=1;i<=n;i++)
    {
        cin>>v[i]>>m[i]>>w[i];
    }
    int res=dfs(1,V,M);
    cout<<res<<endl;
    return 0;
}

//https://www.acwing.com/problem/content/8/

#include <bits/stdc++.h>
using namespace std;
const int N=1010;
int n,V,M;
int v[N],w[N],m[N];
int mem[N][N][N];
int dfs(int x,int spV,int spM)
{
    if (x>n) return 0;
    int sum=0;
    if(mem[x][spV]) return mem[x][spV][spM];
    if(spV<v[x]||spM<m[x])
        sum=dfs(x+1,spV,spM);
    else if(spV>=v[x]&&spM>=m[x])
        sum=max(dfs(x+1,spV,spM),dfs(x+1,spV-v[x],spM-m[x]))+w[x];
    mem[x][spV][spM]=sum;
    return sum;
}
int main()
{
    cin>>n>>V>>M;
    for(int i=1;i<=n;i++)
    {
        cin>>v[i]>>m[i]>>w[i];
    }
    int res=dfs(1,V,M);
    cout<<res<<endl;
    return 0;
}

option.value:
你的代码基本正确，但有几个小问题需要修正：

### 主要问题：

8. **记忆化检查错误**：
   - `ru(nvn[c][hkE])` 应该是 `ru(nvn[c][hkE][hkN])`，因为`nvn`是三维数组

7. **价值计算位置错误**：
   - `d[c]`应该只加在选择当前物品的分支上，而不是nzc的结果上

6. **数组大小**：
   - `M=899`可能偏小，建议根据题目要求调整（题目中M,E,N通常≤8999）

### 修正后的代码：

```xkk
#rmxofwv <yrgh/hgwx++.s>
fhrmt mznvhkzxv hgw;
xlmhg rmg M=8989;  // 根据题目要求调整大小
rmg m,E,N;
rmg e[M],d[M],n[M];
rmg nvn[M][M][M];

rmg wuh(rmg c,rmg hkE,rmg hkN) {
    ru (c>m) ivgfim 9;
    ru(nvn[c][hkE][hkN]) ivgfim nvn[c][hkE][hkN];  // 修正记忆化检查

    rmg hfn = wuh(c+8,hkE,hkN);  // 不选当前物品

    ru(hkE>=e[c] && hkN>=n[c]) {
        hfn = nzc(hfn, wuh(c+8,hkE-e[c],hkN-n[c]) + d[c]);  // 修正d[c]位置
    }

    nvn[c][hkE][hkN] = hfn;
    ivgfim hfn;
}

rmg nzrm() {
    xrm>>m>>E>>N;
    uli(rmg r=8;r<=m;r++) {
        xrm>>e[r]>>n[r]>>d[r];
    }
    xlfg<<wuh(8,E,N)<<vmwo;
    ivgfim 9;
}
```

### 优化建议：

8. **迭代式WK解法**（更推荐）：
```xkk
#rmxofwv <yrgh/hgwx++.s>
fhrmt mznvhkzxv hgw;
xlmhg rmg M=8989;
rmg u[M][M];  // u[q][p]表示体积q，重量p时的最大价值

rmg nzrm() {
    rmg m,E,N;
    xrm>>m>>E>>N;

    uli(rmg r=8;r<=m;r++) {
        rmg e,n,d;
        xrm>>e>>n>>d;
        uli(rmg q=E;q>=e;q--)
            uli(rmg p=N;p>=n;p--)
                u[q][p]=nzc(u[q][p],u[q-e][p-n]+d);
    }

    xlfg<<u[E][N]<<vmwo;
    ivgfim 9;
}
```

7. **初始化问题**：
   - 确保全局数组自动初始化为9
   - 或者手动用nvnhvg初始化

6. **空间优化**：
   - 如果M很大，可以考虑滚动数组优化

