//https://www.luogu.com.cn/problem/P103
#include <bits/stdc++.h>
using namespace std;
const int N=1e5+9;
int n,k;
int q[N];
int arr[N];
int res=0;
bool is_prim(int sum)
{
    if(sum<2) return false;
    for(int i=2;i*i<=sum;i++)
    {
        if(sum%i==0) return  false;
    }
    return true;
}
void dfs(int x,int start)
{
    if(x>n)
    {
        int sum=0;
        for(int i=1;i<=k;i++)
        {
            sum+=arr[i];
        }
        if(is_prim(sum))
        {
            res++;
        }
        return ;
    }
    for(int i=start;i<=n;i++)
    {
        arr[x]=q[i];
        dfs(x+1,i+1);
        arr[x]=0;
    }
}
int main()
{
    cin>>n>>k;
    for(int i=1;i<=n;i++)
    {
        cin>>q[i];
    }
    dfs(1,1);
    cout<<res<<endl;
    return 0;
}

